chunk.argumentsDelta:
{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-sonnet-vs-opus-t5/cell-u6UerO/src/parse.js","content":"import { CliError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/**
 * Parses the build graph text into a map of task names to costs and a map
 * of task names to their (deduplicated) dependency name sets.
 */
export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const deps = new Map()
  const depEntries = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'task') {
      if (tokens.length !== 3) {
        throw new CliError(`error: line ${lineNo}: expected task <name> <cost>`, 2)
      }
      const name = tokens[1]
      const costStr = tokens[2]
      if (!NAME_RE.test(name)) {
        throw new CliError(`error: line ${lineNo}: invalid task name ${name}`, 2)
      }
      if (!COST_RE.test(costStr)) {
        throw new CliError(`error: line ${lineNo}: cost must be a non-negative integer`, 2)
      }
      if (tasks.has(name)) {
        throw new CliError(`error: line ${lineNo}: task ${name} is declared twice`, 2)
      }
      tasks.set(name, parseInt(costStr, 10))
      deps.set(name, new Set())
    } else if (directive === 'dep') {
      if (tokens.length < 3) {
        throw new CliError(`error: line ${lineNo}: expected dep <name> <dependency>...`, 2)
      }
      const owner = tokens[1]
      const list = tokens.slice(2)
      depEntries.push({ owner, list })
    } else {
      throw new CliError(`error: line ${lineNo}: unknown directive ${directive}`, 2)
    }
  }

  for (const { owner, list } of depEntries) {
    if (!tasks.has(owner)) {
      throw new CliError(`error: unknown task ${owner}`, 2)
    }
    for (const dep of list) {
      if (!tasks.has(dep)) {
        throw new CliError(`error: unknown task ${dep}`, 2)
      }
    }
  }

  for (const { owner, list } of depEntries) {
    const set = deps.get(owner)
    for (const dep of list) set.add(dep)
  }

  return { tasks, deps }
}
"}

