chunk.argumentsDelta:
{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-sonnet-vs-opus-t5/cell-u6UerO/src/cycle.js","content":"/**
 * Finds the first cycle a depth-first search discovers when it starts from
 * each task in ascending name order and walks each task's dependencies in
 * ascending name order. Returns the cycle as an array of names, starting
 * and ending with the re-entered task, or null when the graph is acyclic.
 */
export function findCycle(tasks, deps) {
  const names = [...tasks.keys()].sort()
  const state = new Map()
  const stack = []

  function dfs(node) {
    state.set(node, 1)
    stack.push(node)
    const depList = [...(deps.get(node) || [])].sort()
    for (const dep of depList) {
      const st = state.get(dep)
      if (st === 1) {
        const idx = stack.indexOf(dep)
        return stack.slice(idx).concat(dep)
      }
      if (st !== 2) {
        const res = dfs(dep)
        if (res) return res
      }
    }
    stack.pop()
    state.set(node, 2)
    return null
  }

  for (const name of names) {
    if (state.get(name) === 2) continue
    const res = dfs(name)
    if (res) return res
  }
  return null
}
"}

