chunk.argumentsDelta:
{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-sonnet-vs-opus-t5/cell-u6UerO/src/schedule.js","content":"/**
 * Computes the unlimited-worker schedule: each task's start, finish and
 * wave depth. Assumes the graph is acyclic.
 */
export function computeSchedule(tasks, deps) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()

  function compute(name) {
    if (finish.has(name)) return
    const depList = deps.get(name)
    let s = 0
    let d = 0
    for (const dep of depList) {
      compute(dep)
      const df = finish.get(dep)
      if (df > s) s = df
      const dd = depth.get(dep) + 1
      if (dd > d) d = dd
    }
    start.set(name, s)
    finish.set(name, s + tasks.get(name))
    depth.set(name, d)
  }

  for (const name of tasks.keys()) compute(name)

  return { start, finish, depth }
}
"}

