export function computeSchedule(tasks, deps) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()

  function compute(name) {
    if (finish.has(name)) return
    const depList = deps.get(name)
    let s = 0
    let d = 0
    for (const dep of depList) {
      compute(dep)
      const df = finish.get(dep)
      if (df > s) s = df
      const dd = depth.get(dep) + 1
      if (dd > d) d = dd
    }
    start.set(name, s)
    finish.set(name, s + tasks.get(name))
    depth.set(name, d)
  }

  for (const name of tasks.keys()) compute(name)

  return { start, finish, depth }
}
