{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-sonnet-vs-opus-t5/cell-u6UerO/src/pack.js","content":"/**
 * Simulates the build graph on a fixed number of workers, using the
 * greatest-longest-remaining-chain priority to pick among ready tasks.
 * Assumes the graph is acyclic.
 */
export function runPack(tasks, deps, workerCount) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, depSet] of deps) {
    for (const dep of depSet) {
      dependents.get(dep).push(name)
    }
  }

  const priority = new Map()
  function computePriority(name) {
    if (priority.has(name)) return priority.get(name)
    let max = 0
    for (const d of dependents.get(name)) {
      const p = computePriority(d)
      if (p > max) max = p
    }
    const val = tasks.get(name) + max
    priority.set(name, val)
    return val
  }
  for (const name of tasks.keys()) computePriority(name)

  const remaining = new Set(tasks.keys())
  const finish = new Map()
  const busyUntil = new Array(workerCount).fill(0)
  const logs = Array.from({ length: workerCount }, () => [])
  let currentTime = 0

  while (remaining.size > 0) {
    let progressed = true
    while (progressed) {
      progressed = false

      let freeIdx = -1
      for (let i = 0; i < workerCount; i++) {
        if (busyUntil[i] <= currentTime) {
          freeIdx = i
          break
        }
      }
      if (freeIdx === -1) break

      let best = null
      for (const name of remaining) {
        const depList = deps.get(name)
        let ready = true
        for (const dep of depList) {
          const f = finish.get(dep)
          if (f === undefined || f > currentTime) {
            ready = false
            break
          }
        }
        if (!ready) continue
        if (best === null) {
          best = name
        } else {
          const p1 = priority.get(name)
          const p2 = priority.get(best)
          if (p1 > p2 || (p1 === p2 && name < best)) best = name
        }
      }
      if (best === null) break

      const cost = tasks.get(best)
      const start = currentTime
      const fin = start + cost
      busyUntil[freeIdx] = fin
      logs[freeIdx].push({ name: best, start, finish: fin })
      finish.set(best, fin)
      remaining.delete(best)
      progressed = true
    }

    if (remaining.size === 0) break

    let next = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (busyUntil[i] > currentTime && busyUntil[i] < next) next = busyUntil[i]
    }
    if (next === Infinity) break
    currentTime = next
  }

  let makespan = 0
  for (const f of finish.values()) {
    if (f > makespan) makespan = f
  }

  return { logs, makespan }
}
"}

