{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-sonnet-vs-opus-t5/cell-u6UerO/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { CliError } from './errors.js'
import { parseGraph } from './parse.js'
import { findCycle } from './cycle.js'
import { computeSchedule } from './schedule.js'
import { runPack } from './pack.js'

function readStdin() {
  return new Promise((resolve, reject) => {
    let data = ''
    process.stdin.setEncoding('utf8')
    process.stdin.on('data', (chunk) => {
      data += chunk
    })
    process.stdin.on('end', () => resolve(data))
    process.stdin.on('error', reject)
  })
}

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!/^[1-9][0-9]*$/.test(argv[1])) {
      throw new CliError('error: workers must be a positive integer', 2)
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new CliError('error: usage: cli.js waves|explain|pack <workers>', 2)
}

async function main() {
  const input = await readStdin()
  const { mode, workers } = parseArgs(process.argv.slice(2))

  const { tasks, deps } = parseGraph(input)

  const cycle = findCycle(tasks, deps)
  if (cycle) {
    process.stderr.write(`error: cycle: ${cycle.join(' -> ')}\n`)
    process.exit(3)
    return
  }

  if (mode === 'waves') {
    const { finish, depth } = computeSchedule(tasks, deps)
    const names = [...tasks.keys()].sort()
    const waves = new Map()
    let maxDepth = -1
    for (const name of names) {
      const d = depth.get(name)
      if (!waves.has(d)) waves.set(d, [])
      waves.get(d).push(name)
      if (d > maxDepth) maxDepth = d
    }
    let out = ''
    for (let k = 0; k <= maxDepth; k++) {
      const wave = waves.get(k) || []
      out += `wave ${k}: ${wave.join(' ')}\n`
    }
    let total = 0
    for (const name of names) {
      const f = finish.get(name)
      if (f > total) total = f
    }
    out += `total ${total}\n`
    process.stdout.write(out)
  } else if (mode === 'explain') {
    const { start, finish, depth } = computeSchedule(tasks, deps)
    const names = [...tasks.keys()].sort()
    let out = ''
    for (const name of names) {
      out += `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}\n`
    }
    let total = 0
    for (const name of names) {
      const f = finish.get(name)
      if (f > total) total = f
    }
    out += `total ${total}\n`
    process.stdout.write(out)
  } else if (mode === 'pack') {
    const { logs, makespan } = runPack(tasks, deps, workers)
    let out = ''
    for (let i = 0; i < workers; i++) {
      const entries = logs[i].map((e) => ` ${e.name}@${e.start}-${e.finish}`).join('')
      out += `worker ${i}:${entries}\n`
    }
    out += `makespan ${makespan}\n`
    process.stdout.write(out)
  }
}

main().catch((err) => {
  if (err instanceof CliError) {
    process.stderr.write(err.message + '\n')
    process.exit(err.code)
  } else {
    throw err
  }
})
"}

